exercise.starter:
def reporting_slots(slots):
    """Return the indices of slots whose values are truthy."""
    pass

exercise.solution:
def reporting_slots(slots):
    # truthiness test straight on the value; indices via enumerate
    return [i for i, v in enumerate(slots) if v]

exercise.starter:
def sterilizer_status(temp, pressure):
    """Return one of abort/heat/pressurize/run by the priority spec."""
    pass

exercise.solution:
def sterilizer_status(temp, pressure):
    # safe window first, as two chained comparisons
    if 100 <= temp <= 125 and 110 <= pressure <= 150:
        return "run"
    if temp > 125 or pressure > 150:
        return "abort"
    if temp < 100:
        return "heat"
    return "pressurize"

exercise.starter:
def dual_report(changes):
    """Return [(int(x), round(x)) ...] for each change x."""
    pass

exercise.solution:
def dual_report(changes):
    # firmware: int() truncates toward zero; display: round() to even
    return [(int(x), round(x)) for x in changes]
